  const { container, user } = renderPage(
    fakeApi([{ id: '1', title: 'Buy milk', completed: false }]),
  );
  await todoList();

  await submitTitle(user, '');
  await screen.findByRole('alert');

  expect(await axe(container)).toHaveNoViolations();
});
